INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("フリーマーケットを訪れたジータが出会ったのは\n城をこっそり抜け出していたペコリーヌだった。", 40, 1, "ペコリーヌとの出会い", 7, 91002, 2834, 0, 20063115, 5118061, 10118, 8, 2, "青空の下で謁見", "フリーマーケット会場");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ジータたちがフリーマーケットを巡っていると\n露店を出していたマホに声をかけられる。", 40, 1, "マホとの出会い", 7, 91002, 2835, 0, 20063115, 5118062, 10118, 8, 2, "未来の騎空団\nマスコット？", "フリーマーケット会場");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ジータが騎空団への依頼を確認していると、\n高笑いをしながらアキノが現れる。", 40, 1, "アキノとの出会い", 7, 91002, 2837, 0, 20063115, 5118063, 10118, 8, 2, "お嬢さまからの\n緊急依頼", "ランドソル市街地");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ジータたちは、フリーマーケット会場で\n少し困った様子のジュンを見かける。", 40, 1, "ジュンとの出会い", 18, 91002, 4108402, 0, 20063115, 5118064, 10118, 8, 2, "黄金色の悩みごと", "フリーマーケット会場");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("フリーマーケットの隅で開かれる格闘大会──\nそこにはカオリもいて……？", 40, 1, "カオリとの出会い", 18, 91002, 4107402, 0, 20063115, 5118065, 10118, 8, 2, "白熱！　格闘大会！", "フリーマーケット会場");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("太鼓祭を控えるオーエド町──\nジータは、困った様子のニノンと出会う。", 40, 1, "ニノンとの出会い", 16, 91002, 9000227, 1, 20063115, 5118066, 10118, 8, 2, "祭り太鼓はオーエドの華", "オーエド町");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ビカラはイベントに出演中のスズナを見かける。\nしかし、スズナはどこか困っているようで……？", 40, 1, "スズナとの出会い", 19, 91002, 2101181, 0, 20063115, 5118067, 10118, 8, 3, "人気者は遅れて\nやってくる", "フリーマーケット会場");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ビカラたちが街を散策していると、通りかかった\nナナカが興奮した様子で近づいてきて……？", 40, 1, "ナナカとの出会い", 18, 91002, 4109402, 0, 20063115, 5118068, 10118, 8, 3, "巫女・ミーツ・魔法少女", "ランドソル市街地");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ネズ耳をなくしてしまい絶望するビカラ。同じ頃\nキャルとコッコロは落とし物を拾っており……", 40, 1, "キャル＆コッコロとの出会い", 18, 91002, 4305402, 0, 20063115, 5118069, 10118, 8, 3, "ネズ耳は二度なくなる", "フリーマーケット会場");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("街外れでひと休みをしていたビカラたちは、\nすっかりゴキゲンな様子のユカリと出会う。", 40, 1, "ユカリとの出会い", 18, 91002, 4101402, 0, 20063115, 5118070, 10118, 8, 3, "この出会いにカンパイ！", "ランドソル市街地");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ビカラは、人混みに怯えるアオイを心配し、\n陽気に声をかけるも……", 40, 1, "アオイとの出会い", 18, 91002, 4106402, 0, 20063115, 5118071, 10118, 8, 3, "陰陽アンサンブル", "ランドソル市街地");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ビカラがフリーマーケット会場を歩いていると\n占いをしていたシノブに声をかけられる。", 40, 1, "シノブとの出会い", 7, 91002, 2836, 1, 20063115, 5118072, 10118, 8, 3, "運試し十番勝負！", "フリーマーケット会場");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (0, 0, 0, "オープニング", 0, 0, 0, 0, 20063115, 5118600, 10118, 0, 1, "彼女たちの新たな日常", 0);
